mkdir -p "$TMPDIR/chk" && cat > "$TMPDIR/chk/check.py" <<'EOF'
import csv,sys,os
from datetime import date,timedelta as td
D=sys.argv[1]; CHECK=date(2026,11,27); P=date.fromisoformat
rows={}
def rd(n):
    with open(os.path.join(D,n),encoding='utf-8') as f:
        r=list(csv.DictReader([l for l in f if not l.startswith('#')]))
    rows[n]=len(r); return r
def txt(n):
    with open(os.path.join(D,n),encoding='utf-8') as f: L=f.read().splitlines()
    rows[n]=len(L); return L
con=rd('contracts_register_2026.csv'); reg={r['id']:P(r['date_filed']) for r in rd('registration_M1M2_2026.csv')}
ot=rd('overtime_weekly_2026.csv'); pl=rd('payroll_lines_2026-07_to_10.csv'); att=rd('attendance_2026-11.csv')
runs=rd('payroll_runs_2026.csv'); lv={r['id']:int(r['days']) for r in rd('leave_decisions_2026.csv')}
rd('absences_2026.csv'); er=rd('employee_records_2026.csv'); med=rd('medical_exams.csv'); tr=rd('training_proofs_2026.csv')
notes=txt('overtime_notices_folder.txt'); ss=txt('safety_statement_2019.md')
start={r['id']:P(r['start_date']) for r in con}; F=[]; N=[]
def f(i,rule,n,d): F.append(f"{i} | {rule} | {n} | {d}")
late=[i for i in start if i not in reg or reg[i]>start[i]-td(1)]
eq=[i for i in start if reg.get(i)==start[i]-td(1)]
if late: f('L02','M1/M2 filed by the day before start',len(late),','.join(f"{i} filed {reg[i]} start {start[i]}" for i in late))
N+= [f"L02 {i} filed exactly the day before start, passes" for i in eq]
over=[r for r in ot if float(r['overtime_hours'])>8]
if over: f('L05','overtime at most 8 h a week',len({r['id'] for r in over}),f"{len(over)} weeks of {','.join(sorted({r['overtime_hours']+'h' for r in over}))} for {','.join(sorted({r['id'] for r in over}))}")
near=sorted({(r['id'],r['overtime_hours']) for r in ot if 7<=float(r['overtime_hours'])<=8})
N+= [f"L05 {i} {h} h every week, under 8, passes" for i,h in near]
signed=[l for l in notes if '|' in l and l[:4].isdigit() and l[:4]=='2026' and not l.rstrip().endswith('Signed by:')]
if ot and not signed: f('L06','signed written notice for each overtime period',len({r['id'] for r in ot}),f"{len(ot)} weeks in 2026, no 2026 notice; the 2019 notice has a blank sign-off line")
nol=[r for r in pl if r['overtime_line_hours'].strip()=='' ]
otm={(r['id'],r['week_start'][:7]) for r in ot if float(r['overtime_hours'])>0}
if nol: f('L07','overtime on its own pay line',len({r['id'] for r in nol}),f"{len(nol)} pay lines blank for {','.join(sorted({r['id'] for r in nol}))}; months with overtime and blank line: {sum((r['id'],r['month']) in otm for r in nol)}")
miss=[r for r in att if not (r['start'] and r['end']) and r['code']!='ABS']
abs_=[r for r in att if r['code']]
if miss: f('L04','start and end for every working day',len({r['id'] for r in miss}),f"{len(miss)} rows tick only for {','.join(sorted({r['id'] for r in miss}))}")
if abs_: N.append(f"L04 {len(abs_)} rows coded {','.join(sorted({r['code'] for r in abs_}))} for {','.join(sorted({r['id'] for r in abs_}))}, absence not a working day, passes")
def lim(pe):
    d=pe+td(15)
    while d.weekday()>=5: d+=td(1)
    return d
lp=[r for r in runs if P(r['pay_date'])>lim(P(r['period_end']))]
if lp: f('L08','pay within 15 days, free day moves it',len(lp),'; '.join(f"period {r['period_end']} paid {r['pay_date']} limit {lim(P(r['period_end']))}" for r in lp))
N+= [f"L08 period {r['period_end']}: day 15 is {(P(r['period_end'])+td(15)).strftime('%a')}, limit moves to {lim(P(r['period_end']))}, paid {r['pay_date']}, passes (weekends only, holiday list NOT IN FILES)" for r in runs if (P(r['period_end'])+td(15)).weekday()>=5 and r not in lp]
def m6(s):
    y,m=s.year,s.month+6; y+=(m-1)//12; m=(m-1)%12+1; return date(y,m,min(s.day,28))
owed=[i for i in start if m6(start[i])<=CHECK]
lb=[i for i in owed if lv.get(i,0)<20]
if lb: f('L09','leave decision of at least 20 days after 6 months',len(lb),','.join(f"{i} {'missing' if i not in lv else str(lv[i])+' days'}" for i in lb))
N+= [f"L09 {i} starts {start[i]}, 6 months reached {m6(start[i])}, after the check date, not yet owed" for i in start if m6(start[i])>CHECK]
N+= [f"L09 {i} exactly 20 days, passes" for i in lv if lv[i]==20]
emp=[(r['id'],k) for r in er for k in r if k!='id' and not r[k].strip()]
if emp: f('L03','all 22 fields filled',len({i for i,_ in emp}),f"{len(emp)} empty fields: "+','.join(f"{i} {k}" for i,k in emp))
c24=date(2024,11,27)
old=[r['id'] for r in med if P(r['last_exam_date'])<c24]
if old: f('L12','last exam at most 24 months old on 27 Nov 2026',len(old),f"{','.join(old)} last exam {','.join(sorted({r['last_exam_date'] for r in med if r['id'] in old}))}")
N+= [f"L12 {r['id']} exam {r['last_exam_date']}, {(P(r['last_exam_date'])-c24).days} days inside 24 months, passes" for r in med if c24<=P(r['last_exam_date'])<c24+td(31)]
titles={l[2:].strip() for l in ss if l.startswith('- ')}
mt=sorted({r['role'] for r in con}-titles)
if mt: f('L10','safety statement names every job position',len(mt),f"{','.join(mt)} missing ({sum(r['role'] in mt for r in con)} workers); {len({r['role'] for r in con})} titles in register")
nh=[i for i in start if start[i]>CHECK-td(365)]; td_={r['id']:r for r in tr}
lt=[i for i in nh if i not in td_ or P(td_[i]['training_date'])>start[i]]
if lt: f('L13','training on or before hire date',len(lt),','.join(lt))
N+= [f"L13 {i} trained on the hire day {start[i]}, passes" for i in nh if i in td_ and P(td_[i]['training_date'])==start[i]]
print("ROWS "+'; '.join(f"{k} {v}" for k,v in rows.items()))
print("FINDINGS (id | rule | number | detail)"); [print(x) for x in F]
print("NEAR MISSES"); [print(x) for x in N]
csvrows=sum(v for k,v in rows.items() if k.endswith('.csv'))
print(f"TOTALS rows read {csvrows} (CSV data rows; plus {rows['overtime_notices_folder.txt']} txt and {rows['safety_statement_2019.md']} md lines), findings {len(F)}, near misses checked {len(N)}")
EOF
python3 -I "$TMPDIR/chk/check.py" "$PWD"
